<h1>Seller Analytics</h1><div class="grid"><div class="card"><div class="stat"><?= e($stats['total_auctions'] ?? 0) ?></div><p>Total auctions created</p></div><div class="card"><div class="stat"><?= e($stats['sold'] ?? 0) ?></div><p>Total auctions won</p></div><div class="card"><div class="stat"><?= e(number_format((float)($stats['avg_sale'] ?? 0), 2)) ?></div><p>Average sale price</p></div><div class="card"><div class="stat"><?= e(number_format((float)($stats['revenue'] ?? 0), 2)) ?></div><p>Total revenue</p></div><div class="card"><div class="stat"><?= e($stats['popular_category'] ?? 'N/A') ?></div><p>Most popular category</p></div></div><div class="card"><h2>Sales Trend</h2><table><tr><th>Date</th><th>Sold Auctions</th><th>Revenue</th></tr><?php foreach($trend as $row): ?><tr><td><?= e($row['sale_day']) ?></td><td><?= e($row['sold_count']) ?></td><td><?= e(number_format((float)$row['revenue'], 2)) ?></td></tr><?php endforeach; ?></table></div>
